  for (const el of all) {
    const r = el.getBoundingClientRect();
    if (r.width < 18 || r.height < 18) continue;
    if (r.left > 110 || r.top < 130 || r.top > 430) continue;
    const txt = (el.textContent || '').replace(/\s+/g, ' ').trim();
    const cs = getComputedStyle(el);
    const cursor = cs.cursor;
    const hasClick = typeof el.onclick === 'function';
    const isLink = el.tagName === 'A';
    const isListItem = el.tagName === 'LI';
    if (!(isLink || hasClick || cursor === 'pointer' || isListItem)) continue;
    clickable.push({
      tag: el.tagName,
      className: el.className,
      text: txt.slice(0, 60),
      left: Math.round(r.left),
      top: Math.round(r.top),
      width: Math.round(r.width),
      height: Math.round(r.height),
