}"}

{"function":"() => {
  const pickByExactText = (text) => {
    const nodes = Array.from(document.querySelectorAll('*')).filter((el) => {
      const t = (el.textContent || '').trim();
      if (t !== text) return false;
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    });
    if (nodes.length === 0) return null;
    // Prefer smallest matching box to avoid large containers
    return nodes.sort((a, b) => {
      const ra = a.getBoundingClientRect();
      const rb = b.getBoundingClientRect();
      return ra.width * ra.height - rb.width * rb.height;
    })[0];
  };

  const styleInfo = (el) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    return {
      tag: el.tagName,
      className: el.className,
      fontFamily: cs.fontFamily,
      fontSize: cs.fontSize,
      fontWeight: cs.fontWeight,
      lineHeight: cs.lineHeight,
      letterSpacing: cs.letterSpacing,
      color: cs.color,
      backgroundColor: cs.backgroundColor,
      borderColor: cs.borderColor,
      borderWidth: cs.borderWidth,
      borderRadius: cs.borderRadius,
      height: Math.round(r.height),
      width: Math.round(r.width),
      padding: `${cs.paddingTop} ${cs.paddingRight} ${cs.paddingBottom} ${cs.paddingLeft}`,
      margin: `${cs.marginTop} ${cs.marginRight} ${cs.marginBottom} ${cs.marginLeft}`,
    };
  };

  const labels = [
    'Options',
    'Reopen last tab on connect',
    'Disable internet access (for metered or slow connections)',
    'Advanced CLI AutoComplete',
    'Enable dark theme',
    'Development Settings',
    'Show warnings',
    'Connect',
    'Update Firmware'
  ];

  const picked = Object.fromEntries(labels.map((label) => [label, pickByExactText(label)]));
  const styled = Object.fromEntries(labels.map((label) => [label, styleInfo(picked[label])]));

  // Estimate row density for first options group by collecting visible row labels
  const rowTexts = [
    'Reopen last tab on connect',
    'Disable internet access (for metered or slow connections)',
    'Opt out of the anonymised collection of statistics data',
    'Advanced CLI AutoComplete',
    'Enable manual connection mode',
    'Enable virtual connection mode',
    'Enable legacy rendering for 3D model (for low performance devices)',
    'Enable dark theme',
    'Automatically open DevTools in development mode',
    'Show notifications for long operations'
  ];

  const rowRects = rowTexts
    .map((t) => pickByExactText(t))
    .filter(Boolean)
    .map((el) => ({ text: (el.textContent || '').trim(), rect: el.getBoundingClientRect() }))
    .sort((a, b) => a.rect.top - b.rect.top);

  const verticalSteps = [];
  for (let i = 1; i < rowRects.length; i += 1) {
    verticalSteps.push(Math.round(rowRects[i].rect.top - rowRects[i - 1].rect.top));
  }

  const optionPanel = picked['Reopen last tab on connect']?.closest('fieldset, .cf_box, .tab-options, .content_wrapper, .content, .subtab') || null;
  const body = document.body;

  return {
    styled,
    rowMetrics: {
      rowCount: rowRects.length,
      rowHeights: rowRects.map((r) => Math.round(r.rect.height)),
      verticalSteps,
      minTop: rowRects.length ? Math.round(rowRects[0].rect.top) : null,
      maxBottom: rowRects.length ? Math.round(rowRects[rowRects.length - 1].rect.bottom) : null,
    },
