    const nodes = Array.from(document.querySelectorAll('*')).filter((el) => (el.textContent || '').trim() === text);
    if (!nodes.length) return null;
    return nodes.sort((a, b) => a.getBoundingClientRect().width * a.getBoundingClientRect().height - b.getBoundingClientRect().width * b.getBoundingClientRect().height)[0];
  };

  const row1Label = byText('Reopen last tab on connect');
  const row4Label = byText('Advanced CLI AutoComplete');

  const row1Container = row1Label?.closest('.option, .cf_row, .toggle, .content_wrapper > div, div') || row1Label?.parentElement;
  const row4Container = row4Label?.closest('.option, .cf_row, .toggle, .content_wrapper > div, div') || row4Label?.parentElement;

