  const row4Prev = row4Label?.previousElementSibling || null;

  const activeOptionsTab = document.querySelector('.tab_options.active') || document.querySelector('.tab_options');
  const activeOptionsLink = activeOptionsTab?.querySelector('a') || null;

  const connectButton = document.querySelector('.connection_button') || null;
  const connectButtonCircle = document.querySelector('.connect_state') || connectButton?.querySelector('a, .icon, i, span') || null;
  const fwButton = document.querySelector('.firmware_flasher_button') || null;
