  const optionsTitle = byText('Options');

  const matches = Array.from(document.querySelectorAll('[class]')).filter((el) => {
    const cls = (el.className || '').toString();
    return /spacer_box|tab_options|connection_button|firmware_flasher|toggle|switch|slider|tabicon|subtab/i.test(cls);
  }).slice(0, 80);

  return {
    optionsTab: summarizeEl(activeOptionsTab),
    optionsTabLink: summarizeEl(activeOptionsLink),
    optionsTitle: summarizeEl(optionsTitle),
    row1Label: summarizeEl(row1Label),
    row1Prev: summarizeEl(row1Prev),
    row1Container: summarizeEl(row1Container),
    row4Label: summarizeEl(row4Label),
