      return r.width > 0 && r.height > 0;
    });
    if (!visible.length) return null;
    return visible.sort((a, b) => a.getBoundingClientRect().width * a.getBoundingClientRect().height - b.getBoundingClientRect().width * b.getBoundingClientRect().height)[0];
  };

  const style = (el) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    return {
      tag: el.tagName,
      className: el.className,
      text: (el.textContent || '').trim().slice(0, 80),
      fontSize: cs.fontSize,
      fontWeight: cs.fontWeight,
      color: cs.color,
      bg: cs.backgroundColor,
      width: Math.round(r.width),
      height: Math.round(r.height),
    };
  };

  const appVersionSmall = findContains('App Version: 2025.12.2');
  const showLog = Array.from(document.querySelectorAll('*')).find((el) => (el.textContent || '').trim() === 'Show Log');
  const statusBar = Array.from(document.querySelectorAll('*')).find((el) => (el.textContent || '').includes('Port utilization:'));

  return {
    appVersionSmall: style(appVersionSmall),
    showLog: style(showLog),
    statusBar: style(statusBar),
  };
}"}

